// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testRegression_property() public {


        MockVault vault = new MockVault();
        vault.setTotalWeight(100);

        c.init(address(0x1), address(0x2), address(vault));

        c.newAddressProposal(address(0x3), "DAO");

        vm.prank(address(vault));
        vault.setMemberWeight(address(this), 60);
        vm.prank(address(this));
        c.voteProposal(1);

        c.newAddressProposal(address(0x4), "DAO");

        vault.setMemberWeight(address(this), 20);
        vm.prank(address(this));
        c.voteProposal(2);

        vm.prank(address(this));
        c.cancelProposal(1, 2);

        address storedAddr = c.mapPID_address(1);

        assertTrue(storedAddr != address(0), "mapPID_address[1] should be non-zero");
    }
}

contract MockVault {
    uint256 private _totalWeight;
    mapping(address => uint256) private _weights;

    function totalWeight() external view returns (uint256) { return _totalWeight; }
    function setTotalWeight(uint256 w) external { _totalWeight = w; }
    function getMemberWeight(address member) external view returns (uint256) { return _weights[member]; }
    function setMemberWeight(address member, uint256 w) external { _weights[member] = w; }
    function reserveUSDV() external view returns (uint256) { return 0; }
    function reserveVADER() external view returns (uint256) { return 0; }
    function getMemberDeposit(address, address) external view returns (uint256) { return 0; }
    function getMemberLastTime(address, address) external view returns (uint256) { return 0; }
    function grant(address, uint256) external { }
}
